const wl="opening-160-rows", rg="row";
function tot(a,m){return q.run(profiles.arm(a).region(rg).workload(wl).total(m));}
const arms=["typed-stock","typed-scalar","typed-pie","checked-gcc","checked-llvm","unchecked-gcc"];
const out={};
for(const a of arms){
  const o={};
  for(const m of ["instructions","packets","stackLoads","stackStores"]){
    const r=tot(a,m); o[m]= r && r.status ? (r.status==="available"? r.value : r.status+":"+(r.reason||"")) : r;
  }
  out[a]=o;
}
out.regions_note = profiles.regions().map(r=>r.region);
out;

const wl="opening-160-rows", rg="row";
const out={};
for(const a of ["typed-stock","typed-scalar","typed-pie","checked-gcc","checked-llc","checked-llvm","unchecked-gcc"]){
  const o={};
  for(const m of ["instructions","packets","stackLoads","stackStores"]){
    try{const r=q.run(profiles.arm(a).region(rg).workload(wl).total(m));
      o[m]= (r&&("value" in r))? (r.status? r.status+":"+r.value : r.value) : r;
    }catch(e){o[m]="ERR:"+e.message.slice(0,60);}
  }
  out[a]=o;
}
({regions: profiles.regions().map(r=>r.region), out});

var out={};
for(const a of ["typed-stock","typed-scalar","typed-pie","checked-gcc","checked-llc","checked-llvm","unchecked-gcc"]){
  const o={};
  for(const m of ["instructions","packets","stackLoads","stackStores"]){
    try{const r=q.run(profiles.arm(a).region("row").workload("opening-160-rows").total(m));
      o[m]= (r&&("value" in r))? (r.status? r.status+":"+r.value : r.value) : r;
    }catch(e){o[m]="ERR:"+e.message.slice(0,50);}
  }
  out[a]=o;
}
({regions: profiles.regions().map(r=>r.region), out});

(function(){
const res={};
for(const a of ["typed-stock","typed-scalar","typed-pie","checked-gcc","checked-llc","checked-llvm","unchecked-gcc"]){
  const o={};
  for(const m of ["instructions","packets","stackLoads","stackStores"]){
    try{const r=q.run(profiles.arm(a).region("row").workload("opening-160-rows").total(m));
      o[m]= (r&&typeof r==="object"&&"value" in r)? (r.status==="available"? r.value : r.status+":"+(r.reason||"")) : r;
    }catch(e){o[m]="ERR:"+e.message.slice(0,50);}
  }
  res[a]=o;
}
return {regions: profiles.regions().map(r=>r.region), res};
})()

(function(){
const d={};
for(const a of ["typed-stock","typed-scalar","typed-pie","checked-gcc"]){
  try{ d[a]=profiles.arm(a).describe(); }catch(e){ d[a]="ERR:"+e.message.slice(0,80); }
}
return {caps:q.capabilities(), d};
})()

(function(){
const mk=a=>({arm:a, total:profiles.arm(a).region("row").workload("opening-160-rows").total("instructions")});
const res={};
for(const [a,b] of [["typed-stock","typed-scalar"],["typed-stock","typed-pie"],["typed-scalar","typed-pie"]]){
  try{
    const c=q.run(q.compare(mk(a),mk(b)).matchOn("workload","region","unit").percentChange({denominator:"before"}));
    res[a+"->"+b]=c;
  }catch(e){res[a+"->"+b]="ERR:"+e.message.slice(0,120);}
}
return res;
})()

(function(){
const T=(a,m)=>profiles.arm(a).region("row").workload("opening-160-rows").total(m);
const res={};
for(const m of ["instructions","stackLoads","stackStores"]){
  for(const [a,b] of [["typed-stock","typed-scalar"],["typed-scalar","typed-pie"]]){
    try{const c=q.run(q.compare(T(a,m),T(b,m)).matchOn("workload","region","unit").percentChange({denominator:"before"}));
      res[m+"|"+a+"->"+b]={delta:c.delta, pct:c.percentChange??c.percent, matchedOn:c.matchedOn, status:c.status};
    }catch(e){res[m+"|"+a+"->"+b]="ERR:"+e.message.slice(0,120);}
  }
}
return res;
})()

(function(){
const out={};
for(const a of ["typed-stock","typed-scalar","typed-pie"]){
  try{const s=profiles.arm(a).samples(); out[a]=Array.isArray(s)? s.slice(0,4): s;}catch(e){out[a]="ERR:"+e.message.slice(0,120);}
}
return out;
})()

(function(){
const run=a.variant("checked"); const row=run.function("row"); const mid=row.timeline("middle");
const last=mid.last();
const out={events: q.run(mid.count()), last: q.run(last.select("ordinal","pass"))};
for(const op of ["alloca","load","store"]){
  try{
    const m=q.ir.instructions().opcode(op).count();
    out[op]=q.run(m.at(last.after));
  }catch(e){out[op]="ERR:"+e.message.slice(0,100);}
}
return out;
})()

(function(){
const out={};
for(const n of ["numVirtualRegisters","virtualRegisters","frameSize","stackSize","spills"]){
  try{ out[n]=q.run(q.machine.property(n).at(a.variant("checked").function("row").timeline("backend").last().after)); }
  catch(e){ out[n]="ERR:"+e.message.slice(0,90); }
}
return out;
})()
